const body = $json.body || $json;
const required = ['cycle','level','subject'];
for (const k of required) { if (!body[k]) throw new Error('Missing: ' + k); }
return [{ json: body }];

const b = $json;
// Build prompt server-side OR call your frontend prompt builder later.
const cycle = b.cycle;
const level = b.level;
const subject = b.subject;
const unit = b.unit || '';
const lang = b.language || 'fr';
const total = b.totalPoints ?? 20;
const duration = b.durationMin ?? (cycle === 'primaire' ? 60 : cycle === 'college' ? 90 : 120);
const prompt = `Génère une épreuve tunisienne. Sortie JSON strict. Barème=${total}, durée=${duration}. Niveau=${cycle}/${level}. Matière=${subject}. Unité=${unit}. Langue=${lang}.`;
return [{ json: { ...b, prompt } }];
